+import { Hono } from 'hono';
+
+export const listRoutes = new Hono();
+
+listRoutes.get('/', async (c) => {
+  const cursor = c.req.query('cursor') ?? '0';
+  const limit = parseInt(c.req.query('limit') ?? '20', 10);
+
+  const candidates = await c.env.DB
+    .prepare('SELECT * FROM candidates WHERE id > ?1 ORDER BY id LIMIT ?2')
+    .bind(cursor, limit)
+    .all();
+
+  const nextCursor = candidates.results.length === limit
+    ? candidates.results[candidates.results.length - 1].id
+    : null;
+
+  return c.json({ candidates: candidates.results, nextCursor });
+});
